/* ── Skeletons — matches panel's Loading skeleton tokens ── */
@keyframes ks-skeleton-p{0%,100%{opacity:1}50%{opacity:.45}}
.ks-skeleton{background:var(--ks-skeleton-base, rgba(255,255,255,0.06)) !important;border-radius:var(--ks-skeleton-radius,6px) !important;animation:ks-skeleton-p 1.45s ease-in-out infinite}
.ks-skeleton-bar{background:var(--ks-skeleton-shimmer, rgba(255,255,255,0.13)) !important;border-radius:var(--ks-skeleton-radius,6px) !important;animation:ks-skeleton-p 1.45s ease-in-out infinite}
.ks-skeleton-avatar{width:32px;height:32px;border-radius:9999px;background:var(--ks-skeleton-shimmer, rgba(255,255,255,0.13)) !important;animation:ks-skeleton-p 1.45s ease-in-out infinite;flex-shrink:0}
.ks-skeleton-table th .ks-skeleton-bar,.ks-skeleton-table td .ks-skeleton-bar{height:10px}
@media(prefers-reduced-motion:reduce){.ks-skeleton,.ks-skeleton-bar,.ks-skeleton-avatar,.ks-skeleton-card{animation:none !important}}
html[data-ks-reduced-motion='1'] .ks-skeleton,html[data-ks-reduced-motion='1'] .ks-skeleton-bar,html[data-ks-reduced-motion='1'] .ks-skeleton-avatar,html[data-ks-reduced-motion='1'] .ks-skeleton-card{animation:none !important}

/* ── Scroll / Layout helpers ── */
.ks-ip-scroll-area{max-height:calc(100vh - 240px);max-height:calc(100dvh - 240px);overflow:auto}
.ks-page [style*="grid-template-columns:repeat(auto-fill"]{max-height:calc(100vh - 260px);max-height:calc(100dvh - 260px);overflow:auto;padding-right:4px}
.ks-hidden-sm{display:contents}
@media(max-width:640px){.ks-hidden-sm{display:none !important}}
@media(min-width:641px){.ks-only-sm{display:none !important}}
/* Terminal */
.ks-term-bg{background:var(--ks-term-bg, #1e1e1e) !important;color:var(--ks-term-text, #d4d4d4) !important;border-color:var(--ks-term-border, rgba(255,255,255,0.10)) !important}
</style><div class="ks-page">
  {{component:pill_css}}
  <div id="root"><div class="ks-card"><div class="ks-skeleton-bar" style="height:12px;width:40%;margin-bottom:8px"></div><div class="ks-skeleton" style="height:12px;width:65%"></div></div></div>
</div>
<script>
(function () {
  'use strict';
  var sdk = null;
  function esc(s) {
    return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  }
  function toast(m, t) { try { sdk.toast(m, t || 'info'); } catch (e) {} }
  function qparam(name) {
    var q = String(window.KS_PAGE_QUERY || '');
    var m = q.match(new RegExp('[?&]' + name + '=([^&]*)'));
    return m ? decodeURIComponent(m[1].replace(/\+/g, ' ')) : '';
  }
  function pageCfgRaw(name) {
    try {
      var c = window.KS_PAGE_CONFIG || {};
      if (c[name] !== undefined && c[name] !== null && String(c[name]) !== '') return String(c[name]);
    } catch (e) {}
    return '';
  }
  function controlsAutomation() {
    try {
      var cfg = (sdk && sdk.instance && sdk.instance.config) || {};
      if (typeof cfg === 'string') { try { cfg = JSON.parse(cfg); } catch (e) { return {}; } }
      var ic = (cfg && cfg.instance_controls) || {};
      var sc = (ic && ic.shortcuts) || {};
      return (sc && sc.automation) || {};
    } catch (e) { return {}; }
  }
  function cfgBoolBoth(pageName, ctrlName, dflt) {
    var pv = pageCfgRaw(pageName);
    var cv = null;
    try { var a = controlsAutomation(); if (a[ctrlName] !== undefined) cv = a[ctrlName]; } catch (e) {}
    if (cv === false) return false;
    if (pv !== '') return !(pv === 'false' || pv === '0' || pv === 'off');
    if (typeof cv === 'boolean') return cv;
    return dflt;
  }
  function cfgNumBoth(pageName, ctrlName, cap, dflt) {
    var vals = [];
    var pv = pageCfgRaw(pageName);
    if (pv !== '') { var pn = parseInt(pv, 10); if (Number.isFinite(pn) && pn > 0) vals.push(Math.max(1, Math.min(cap, pn))); }
    try {
      var a = controlsAutomation();
      var cv = a[ctrlName];
      var cn = (typeof cv === 'number') ? Math.floor(cv) : parseInt(String(cv == null ? '' : cv), 10);
      if (Number.isFinite(cn) && cn > 0) vals.push(Math.max(1, Math.min(cap, cn)));
    } catch (e) {}
    if (!vals.length) return dflt;
    var m = vals[0];
    for (var i = 1; i < vals.length; i++) if (vals[i] < m) m = vals[i];
    return m;
  }
  function isReadOnly() {
    try {
      var c = window.KS_PAGE_CONFIG || {};
      if (c.read_only === 'true' || c.read_only === '1' || c.read_only === 'on') return true;
    } catch (e) {}
    try { if (controlsAutomation().allow_edit === false) return true; } catch (e) {}
    return false;
  }
  function parentSlug() {
    try {
      var ps = String((sdk && sdk.pageSlug) || '').split('?')[0].split('#')[0].replace(/^\/+|\/+$/g, '');
      if (ps.indexOf('/') > 0) return ps.slice(0, ps.lastIndexOf('/')).split('/')[0];
      if (ps !== '' && ps !== 'edit') return ps;
    } catch (e) {}
    try {
      var s = String((controlsAutomation().slug) || '').replace(/^\/+|\/+$/g, '');
      if (s !== '') return s.split('/')[0];
    } catch (e) {}
    return 'automation';
  }
  function backTo() { return '/instances/' + sdk.instance.id + '/' + parentSlug(); }

  var POWER_OPS = ['start', 'stop', 'restart', 'kill'];
  var STEP_IFS = ['success', 'failure', 'always'];
  var state = {
    draft: null, savedSnapshot: '', activeOthers: 0,
    loading: true, error: '', busy: false, formError: '',
    jobId: null, readOnly: false, ceiling: 1800,
    allowedKinds: ['shell', 'power', 'action'], maxActive: 0,
    pillOff: false
  };
  function el(id) { return document.getElementById(id); }
  function emptyStep() { return { name: '', kind: 'shell', command: '', payload: '', if: 'success' }; }
  function emptyDraft(editing) {
    var k = (editing && editing.kind) || 'shell';
    var payload = (editing && editing.payload) || '';
    return {
      editingId: editing ? editing.id : null,
      editingName: editing ? editing.name : '',
      name: (editing && editing.name) || '',
      kind: k,
      schedule: (editing && editing.schedule) || '',
      command: (editing && editing.command) || '',
      actionId: k === 'action' ? payload : '',
      powerOp: k === 'power' && POWER_OPS.indexOf(payload) >= 0 ? payload : 'restart',
      secretRefs: ((editing && editing.secret_refs) || []).join(', '),
      timeoutSec: (editing && editing.timeout_sec > 0) ? editing.timeout_sec : 300,
      enabled: editing ? !!editing.enabled : true,
      steps: Array.isArray(editing && editing.steps) ? editing.steps.map(function (s) {
        return { name: s.name || '', kind: s.kind || 'shell', command: s.command || '', payload: s.payload || '', if: s.if || 'success', timeout_sec: s.timeout_sec };
      }) : []
    };
  }

  function load() {
    state.loading = true; state.error = '';
    render();
    sdk.listAutomation().then(function (jobs) {
      var list = Array.isArray(jobs) ? jobs : [];
      if (state.jobId === null) {
        var d = emptyDraft(null);
        if (state.allowedKinds.indexOf(d.kind) < 0) d.kind = state.allowedKinds[0] || 'shell';
        state.draft = d;
        state.savedSnapshot = JSON.stringify(d);
        state.activeOthers = list.filter(function (j) { return j.enabled; }).length;
      } else {
        var found = null;
        for (var i = 0; i < list.length; i++) if (list[i].id === state.jobId) found = list[i];
        if (!found) { state.error = 'Job #' + state.jobId + ' not found on this instance.'; state.loading = false; render(); return; }
        var d2 = emptyDraft(found);
        state.draft = d2;
        state.savedSnapshot = JSON.stringify(d2);
        state.activeOthers = list.filter(function (j) { return j.enabled && j.id !== state.jobId; }).length;
      }
      state.loading = false;
      render();
    }).catch(function (e) {
      state.loading = false;
      state.error = (e && e.message) || 'Failed to load job';
      render();
    });
  }
  function dirty() { return state.draft !== null && JSON.stringify(state.draft) !== state.savedSnapshot; }
  function goBack() {
    var done = function () { try { sdk.navigate(backTo()); } catch (e) {} };
    if (!dirty()) { done(); return; }
    var p = null;
    try { p = sdk.confirm('Discard unsaved changes to this job?'); } catch (e) {}
    if (p && p.then) p.then(function (ok) { if (ok) done(); });
    else if (window.confirm('Discard unsaved changes to this job?')) done();
  }
  function submit() {
    var d = state.draft;
    if (!d || state.busy) return;
    var fail = function (m) { state.formError = m; render(); };
    var name = String(d.name || '').trim();
    if (name === '') return fail('Name is required.');
    if (state.allowedKinds.indexOf(d.kind) < 0) return fail('This job kind is disabled by the template.');
    var hasSteps = d.steps.length > 0;
    var kindPayload = '';
    if (d.kind === 'power') {
      if (POWER_OPS.indexOf(d.powerOp) < 0) {
        if (d.powerOp !== '' || !hasSteps) return fail('Pick a power op (start / stop / restart / kill).');
        kindPayload = '';
      } else kindPayload = d.powerOp;
    } else if (d.kind === 'action') {
      kindPayload = String(d.actionId || '').trim();
      if (kindPayload === '' && !hasSteps) return fail('Action ID is required for action jobs (or add steps carrying the plan).');
    }
    var command = d.kind === 'shell' ? d.command : (d.kind === 'action' ? '' : '');
    if (d.kind === 'shell' && String(command).trim() === '' && !hasSteps) return fail('Command is required (or add steps carrying the plan).');
    var timeout = d.timeoutSec > 0 ? Math.floor(d.timeoutSec) : 300;
    if (timeout > state.ceiling) return fail('Timeout ' + timeout + 's exceeds the template maximum of ' + state.ceiling + 's.');
    for (var i = 0; i < d.steps.length; i++) {
      (function (st, n) {
        if (String(st.name || '').trim() === '') return fail('Step ' + n + ': name is required.');
        var sk = st.kind || 'shell';
        if (state.allowedKinds.indexOf(sk) < 0) return fail('Step ' + n + ': kind "' + sk + '" is disabled by the template.');
        if (sk === 'power' && POWER_OPS.indexOf(st.payload || '') < 0) return fail('Step ' + n + ': pick a power op.');
        if (sk === 'action' && String(st.payload || '').trim() === '') return fail('Step ' + n + ': action ID is required.');
        if (sk === 'shell' && String(st.command || '').trim() === '') return fail('Step ' + n + ': command is required.');
        if (st.timeout_sec != null && st.timeout_sec > state.ceiling) return fail('Step ' + n + ': timeout exceeds the template maximum of ' + state.ceiling + 's.');
      })(d.steps[i], i + 1);
      if (state.formError) return;
    }
    if (d.steps.length > 32) return fail('Too many steps (max 32).');
    if (d.enabled && state.maxActive > 0 && state.activeOthers >= state.maxActive) {
      return fail('Too many active jobs (template maximum ' + state.maxActive + '). Disable another job first.');
    }
    var secretRefs = String(d.secretRefs || '').split(',').map(function (s) { return s.trim(); }).filter(Boolean);
    state.busy = true; state.formError = '';
    render();
    var payload = {
      name: name,
      command: command,
      kind: d.kind,
      payload: kindPayload,
      schedule: String(d.schedule || '').trim(),
      enabled: !!d.enabled,
      secret_refs: secretRefs,
      timeout_sec: Math.max(1, Math.min(state.ceiling, timeout)),
      steps: d.steps.map(function (s) {
        var sk = s.kind || 'shell';
        var o = {
          name: String(s.name || '').trim().slice(0, 100),
          kind: sk,
          command: sk === 'shell' ? (s.command || '') : '',
          payload: sk === 'shell' ? '' : String(s.payload || '').trim(),
          if: s.if || 'success'
        };
        if (s.timeout_sec != null && s.timeout_sec > 0) o.timeout_sec = Math.max(1, Math.min(state.ceiling, Math.floor(s.timeout_sec)));
        return o;
      })
    };
    var done = function (msg) {
      state.busy = false;
      toast(msg, 'success');
      try { sdk.navigate(backTo()); } catch (e) {}
    };
    if (d.editingId !== null) sdk.updateAutomationJob(d.editingId, payload).then(function () { done('Job updated'); }, onErr);
    else sdk.createAutomationJob(payload).then(function () { done('Job created'); }, onErr);
    function onErr(e) {
      state.busy = false;
      state.formError = (e && e.message) || 'Failed to save job';
      render();
    }
  }

  function render() {
    var h = '';
    if (state.readOnly) {
      h = '<div class="ks-card" style="text-align:center;padding:32px 16px;color:var(--ks-muted);font-size:13px">Automation editing is disabled for this instance (read-only).<br><button type="button" id="ed-back" class="ks-btn ks-btn-ghost" style="margin-top:12px">Back to automation</button></div>';
      el('root').innerHTML = h;
      wireStatic();
      return;
    }
    if (state.loading) {
      el('root').innerHTML = '<div class="ks-card"><div class="ks-skeleton-bar" style="height:12px;width:40%;margin-bottom:8px"></div><div class="ks-skeleton" style="height:12px;width:65%"></div></div>';
      return;
    }
    if (state.error || !state.draft) {
      h = '<div class="ks-card" style="text-align:center;padding:32px 16px"><p style="font-size:14px;color:var(--ks-heading);margin:0 0 4px">' + (state.jobId === null ? 'Failed to start a new job' : 'Job not found') + '</p>'
        + (state.error ? '<p style="font-size:12px;color:var(--ks-muted);margin:0 0 12px">' + esc(state.error) + '</p>' : '')
        + '<button type="button" id="ed-back" class="ks-btn ks-btn-ghost">Back to automation</button></div>';
      el('root').innerHTML = h;
      wireStatic();
      return;
    }
    var d = state.draft;
    /* Save bar: panel PageFormActionsPill parity — fixed bottom-right
       ks-card ks-pill-anim ks-form-actions-pill with Cancel + Save.
       Header keeps a compact Save for desktop parity; both call submit(). */
    h = '<div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:12px">'
      + '<button type="button" id="ed-back" title="Back to automation" aria-label="Back to automation" class="ks-btn-header ks-icon-btn">{{component:icon_back}}</button>'
      + '<h2 style="font-size:16px;font-weight:600;color:var(--ks-heading);margin:0;flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">' + esc(d.editingId !== null ? ('Edit "' + d.editingName + '"') : 'New job') + ' <span id="ed-dirty" style="font-size:11px;font-weight:400;color:var(--ks-warn)' + (dirty() ? '' : ';display:none') + '">unsaved</span></h2>'
      + '<button type="button" id="ed-save" class="ks-btn ks-btn-primary"' + (state.busy ? ' disabled style="opacity:.5"' : '') + '>' + (state.busy ? 'Saving…' : (d.editingId !== null ? 'Save' : 'Create')) + '</button>'
      + '</div>';
    h += '<div class="ks-card ks-form-card" style="display:flex;flex-direction:column;gap:16px;max-width:48rem">';
    if (state.formError) h += '<p style="font-size:12px;color:var(--ks-bad);margin:0" role="alert">' + esc(state.formError) + '</p>';
    h += '<label class="ks-label" style="display:block">Name<input id="f-name" value="' + esc(d.name) + '" placeholder="Nightly backup" class="ks-input" style="width:100%;box-sizing:border-box;margin-top:4px"></label>';
    h += '<label class="ks-label" style="display:block">Schedule (cron, empty = manual only)<input id="f-schedule" value="' + esc(d.schedule) + '" placeholder="0 4 * * *" class="ks-input ks-mono" style="width:100%;box-sizing:border-box;margin-top:4px"></label>';
    h += '<label class="ks-label" style="display:block">Type<select id="f-kind" class="ks-input" style="width:100%;box-sizing:border-box;margin-top:4px">'
      + (state.allowedKinds.indexOf('shell') >= 0 ? '<option value="shell"' + (d.kind === 'shell' ? ' selected' : '') + '>Shell command — run my own command</option>' : '')
      + (state.allowedKinds.indexOf('power') >= 0 ? '<option value="power"' + (d.kind === 'power' ? ' selected' : '') + '>Power — start / stop / restart / kill</option>' : '')
      + (state.allowedKinds.indexOf('action') >= 0 ? '<option value="action"' + (d.kind === 'action' ? ' selected' : '') + '>Template action — run any action</option>' : '')
      + '</select></label>';
    if (state.allowedKinds.length < 3) h += '<p class="ks-hint" style="margin:-8px 0 0">Some types are disabled by the template.</p>';
    if (d.kind === 'shell') {
      h += '<label class="ks-label" style="display:block">Command<textarea id="f-command" rows="4" placeholder="tar czf /backups/world.tgz /mc/world" class="ks-input ks-mono" style="width:100%;box-sizing:border-box;margin-top:4px">' + esc(d.command) + '</textarea></label>'
        + '<p class="ks-hint" style="margin:-8px 0 0">Runs inside the instance via /bin/sh -c. Optional when steps below carry the plan.</p>';
    }
    if (d.kind === 'power') {
      h += '<label class="ks-label" style="display:block">Power op<select id="f-power" class="ks-input" style="width:100%;box-sizing:border-box;margin-top:4px">'
        + POWER_OPS.map(function (op) { return '<option value="' + op + '"' + (d.powerOp === op ? ' selected' : '') + '>' + op + '</option>'; }).join('') + '</select></label>';
    }
    if (d.kind === 'action') {
      h += '<label class="ks-label" style="display:block">Action ID<input id="f-action" value="' + esc(d.actionId) + '" placeholder="backup-world" class="ks-input ks-mono" style="width:100%;box-sizing:border-box;margin-top:4px"></label>';
    }
    h += '<div><div style="display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:8px"><span style="font-size:13px;color:var(--ks-body)">Steps (optional, run in order)</span>'
      + (d.steps.length < 32 ? '<button type="button" id="f-addstep" style="border:none;background:transparent;color:var(--ks-info);font-size:12px;cursor:pointer">+ Add step</button>' : '') + '</div>';
    if (!d.steps.length) h += '<p class="ks-hint" style="margin:0 0 8px">No steps — the job fires once (type above). Add steps for a plan with per-step if conditions.</p>';
    for (var i = 0; i < d.steps.length; i++) {
      (function (st, n) {
        h += '<div style="border-radius:8px;border:1px solid var(--ks-card-border);background:rgba(0,0,0,0.30);padding:10px;display:flex;flex-direction:column;gap:8px;margin-bottom:8px">'
          + '<div style="display:flex;align-items:center;gap:8px"><span class="ks-mono" style="font-size:11px;color:var(--ks-muted)">' + (n + 1) + '.</span>'
          + '<input data-step="' + n + '" data-f="name" value="' + esc(st.name) + '" placeholder="Step name" aria-label="Step ' + (n + 1) + ' name" class="ks-input" style="flex:1;min-width:0">'
          + '<button type="button" data-rmstep="' + n + '" title="Remove step" aria-label="Remove step ' + (n + 1) + '" style="border:none;background:transparent;color:var(--ks-muted);cursor:pointer;padding:6px">✕</button></div>'
          + '<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px">'
          + '<select data-step="' + n + '" data-f="kind" aria-label="Step ' + (n + 1) + ' type" class="ks-input">'
          + (state.allowedKinds.indexOf('shell') >= 0 ? '<option value="shell"' + ((st.kind || 'shell') === 'shell' ? ' selected' : '') + '>shell</option>' : '')
          + (state.allowedKinds.indexOf('power') >= 0 ? '<option value="power"' + (st.kind === 'power' ? ' selected' : '') + '>power</option>' : '')
          + (state.allowedKinds.indexOf('action') >= 0 ? '<option value="action"' + (st.kind === 'action' ? ' selected' : '') + '>action</option>' : '')
          + '</select>'
          + '<select data-step="' + n + '" data-f="if" aria-label="Step ' + (n + 1) + ' condition" title="success = previous passed · failure = one failed · always = regardless" class="ks-input ks-mono">'
          + STEP_IFS.map(function (c) { return '<option value="' + c + '"' + ((st.if || 'success') === c ? ' selected' : '') + '>if: ' + c + '</option>'; }).join('')
          + '</select></div>'
          + ((st.kind || 'shell') === 'shell'
            ? '<input data-step="' + n + '" data-f="command" value="' + esc(st.command || '') + '" placeholder="echo hello" aria-label="Step ' + (n + 1) + ' command" class="ks-input ks-mono" style="width:100%;box-sizing:border-box">'
            : ((st.kind === 'power')
              ? '<select data-step="' + n + '" data-f="payload" aria-label="Step ' + (n + 1) + ' power op" class="ks-input" style="width:100%;box-sizing:border-box"><option value="">pick op…</option>' + POWER_OPS.map(function (op) { return '<option value="' + op + '"' + (st.payload === op ? ' selected' : '') + '>' + op + '</option>'; }).join('') + '</select>'
              : '<input data-step="' + n + '" data-f="payload" value="' + esc(st.payload || '') + '" placeholder="action-id" aria-label="Step ' + (n + 1) + ' action ID" class="ks-input ks-mono" style="width:100%;box-sizing:border-box">'))
          + '</div>';
      })(d.steps[i], i);
    }
    if (d.steps.length >= 32) h += '<p class="ks-hint">Max 32 steps.</p>';
    h += '</div>';
    h += '<label class="ks-label" style="display:block">Secret refs (comma-separated)<input id="f-refs" value="' + esc(d.secretRefs) + '" placeholder="S3_KEY, S3_SECRET" class="ks-input ks-mono" style="width:100%;box-sizing:border-box;margin-top:4px"></label>';
    h += '<label class="ks-label" style="display:block">Timeout (sec, max ' + state.ceiling + ')<input id="f-timeout" type="number" min="1" max="' + state.ceiling + '" value="' + esc(d.timeoutSec) + '" class="ks-input ks-mono" style="width:100%;box-sizing:border-box;margin-top:4px"></label>';
    h += '<label style="display:flex;align-items:center;gap:8px;font-size:13px;color:var(--ks-body);cursor:pointer"><input type="checkbox" id="f-enabled"' + (d.enabled ? ' checked' : '') + ' style="width:16px;height:16px">Enabled</label>';
    if (state.maxActive > 0) {
      var cur = state.activeOthers + (d.enabled ? 1 : 0);
      h += '<p class="ks-hint" style="margin:-8px 0 0">' + cur + ' of ' + state.maxActive + ' active jobs' + (cur >= state.maxActive ? ' — at the template maximum' : '') + '.</p>';
    }
    h += '</div>';
    /* Bottom save pill (phones + desktop parity): Cancel left, Save right. */
    h += '<div id="ed-savepill-outer" style="position:fixed;bottom:max(0.75rem,env(safe-area-inset-bottom));right:1rem;z-index:40">'
      + '<div id="ed-savepill" class="ks-card ks-pill-anim ks-form-actions-pill' + (state.pillOff ? ' ks-pill-off' : '') + '" style="display:flex;align-items:center;gap:4px;padding:6px;border-radius:8px;box-shadow:0 8px 32px rgba(0,0,0,0.40);--ks-card-padding:6px">'
      + '<div class="ks-pill-content" style="display:flex;align-items:center;gap:4px">'
      + '<button type="button" id="ed-cancel2" class="ks-btn ks-btn-ghost ks-btn-sm">Cancel</button>'
      + '<button type="button" id="ed-save2" class="ks-btn ks-btn-primary ks-btn-sm"' + (state.busy ? ' disabled style="opacity:.5"' : '') + '>' + (state.busy ? 'Saving…' : (d.editingId !== null ? 'Save' : 'Create')) + '</button>'
      + '</div>'
      + '<button type="button" id="ed-pill-toggle" aria-label="Toggle save bar" class="ks-tab ks-pill-toggle" style="display:inline-flex;align-items:center;justify-content:center;flex-shrink:0">' + (state.pillOff ? '{{component:icon_chev_left}}' : '{{component:icon_chev_right}}') + '</button>'
      + '</div></div><div aria-hidden="true" style="height:80px"></div>';
    el('root').innerHTML = h;
    wire();
  }
  function wireStatic() {
    var b = el('ed-back');
    if (b) b.addEventListener('click', goBack);
  }
  function wire() {
    wireStatic();
    var d = state.draft;
    if (!d) return;
    var on = function (id, ev, fn) {
      var n = el(id);
      if (n) n.addEventListener(ev, fn);
    };
    on('ed-save', 'click', submit);
    on('ed-save2', 'click', submit);
    on('ed-cancel2', 'click', goBack);
    on('ed-pill-toggle', 'click', function () { state.pillOff = !state.pillOff; render(); });
    on('f-name', 'input', function () { d.name = el('f-name').value.slice(0, 100); paintDirty(); });
    on('f-schedule', 'input', function () { d.schedule = el('f-schedule').value.slice(0, 100); paintDirty(); });
    on('f-kind', 'change', function () { d.kind = el('f-kind').value; state.formError = ''; render(); });
    on('f-command', 'input', function () { d.command = el('f-command').value.slice(0, 8000); paintDirty(); });
    on('f-power', 'change', function () { d.powerOp = el('f-power').value; });
    on('f-action', 'input', function () { d.actionId = el('f-action').value.slice(0, 128); paintDirty(); });
    on('f-refs', 'input', function () { d.secretRefs = el('f-refs').value.slice(0, 500); paintDirty(); });
    on('f-timeout', 'change', function () {
      var v = Number(el('f-timeout').value) || 300;
      d.timeoutSec = Math.max(1, Math.min(state.ceiling, v));
      render();
    });
    on('f-enabled', 'change', function () { d.enabled = !!el('f-enabled').checked; paintDirty(); });
    on('f-addstep', 'click', function () {
      d.steps.push({ name: '', kind: 'shell', command: '', payload: '', if: 'success' });
      render();
    });
    var rms = document.querySelectorAll('[data-rmstep]');
    for (var ri = 0; ri < rms.length; ri++) {
      (function (b) {
        b.addEventListener('click', function () {
          d.steps.splice(Number(b.getAttribute('data-rmstep')), 1);
          render();
        });
      })(rms[ri]);
    }
    var ins = document.querySelectorAll('[data-step]');
    for (var ii = 0; ii < ins.length; ii++) {
      (function (n) {
        var ev = (n.tagName === 'SELECT' || n.type === 'checkbox') ? 'change' : 'input';
        n.addEventListener(ev, function () {
          var idx = Number(n.getAttribute('data-step'));
          var f = n.getAttribute('data-f');
          var st = d.steps[idx];
          if (!st) return;
          if (f === 'name') st.name = n.value.slice(0, 100);
          else if (f === 'command') st.command = n.value.slice(0, 8000);
          else if (f === 'payload') st.payload = n.value.slice(0, 128);
          else if (f === 'kind' || f === 'if') { st[f] = n.value; render(); return; }
          paintDirty();
        });
      })(ins[ii]);
    }
  }
  function paintDirty() {
    var s = el('ed-dirty');
    if (s) s.style.display = dirty() ? '' : 'none';
  }
  function start(s) {
    sdk = s;
    state.readOnly = isReadOnly();
    state.ceiling = cfgNumBoth('max_timeout_sec', 'max_timeout_sec', 1800, 1800);
    var kinds = [];
    if (cfgBoolBoth('allow_shell', 'allow_shell', true)) kinds.push('shell');
    if (cfgBoolBoth('allow_power', 'allow_power', true)) kinds.push('power');
    if (cfgBoolBoth('allow_actions', 'allow_actions', true)) kinds.push('action');
    state.allowedKinds = kinds.length ? kinds : ['shell', 'power', 'action'];
    state.maxActive = cfgNumBoth('max_active_jobs', 'max_active_jobs', 1000, 0);
    var idRaw = qparam('id');
    state.jobId = (idRaw !== '' && Number.isFinite(Number(idRaw))) ? Number(idRaw) : null;
    load();
  }
  if (window.KSPageSDK) start(window.KSPageSDK);
  else window.addEventListener('ks-page-sdk-ready', function () { start(window.KSPageSDK); }, { once: true });
})();
